add('20_001b',2.5,'16:9，倾斜机位侧面全景，青在画面右下，两脚分踏石面，一腿屈起、一腿伸直，武士横越她头上占据左上方；镜头沿两人相接的腕臂弧线向上摇，落幅同时含青全身与武士横躯。','青右手扣腕不松，左手补上同一腕臂，前脚屈膝踩实、后腿拉直，双臂把来臂举到头上；她的肩先转进去，腰胯接着带动整副身体，武士的冲势继续向前，巨大躯干被她牵到头顶横过。长发和裙摆向反方向甩开，脚下压出两处短尘痕。','灰绿石铺地面在下方斜穿，低处米灰尘线与淡冷灰天空分层；倾斜来自机位。','上方云天冷白漫射，石面返中性弱光，两人下侧明暗仍可辨。','左右脚先后踩实，两下短促压石声；手腕受力细响与巨大躯体的低风叠起。',phase='process',node={'双方.接触':'青双手锁住武士右腕臂','青.接触':'双脚前后踏实石面','武士.阶段':'躯体被牵过青头顶'},meaning='真实下格的双手举臂、前屈后直站位和横过头顶的大体块保留；脚步与补手过程是本次导演补全。')
add('20_002',6.5,'16:9，青正面脸部及双手近景居中，粗壮腕臂沿画面右侧向上出画；镜头随她转体平行移动，落幅保留闭眼鼓腮、紧绷嘴角和双手持续抓握。','青的两手进一步收紧，前臂把粗壮腕部夹牢，脸颊鼓起、双眼闭紧，嘴角却绷出不服输的弯形；她先吸住一口气，抬高肩肘，把武士整条腕臂继续向下拉。开口后胸肩短促震动，话说到句末，双手已经把抓握点拖过脸侧，汗从下颌甩离。','近侧主体间隙露出淡冷灰天空，远处米灰尘层被运动拖成浅色背景。','上方云天冷白柔光，指端与腕部接触缝压暗。','抓握摩擦声更紧，短促吸气后是用力呼气，衣料扭转与庞大躯体裂风同时加重。',ja=['とにかく、','見た目がさらに変になったとはいえ…！！'],tone='闭紧眼用力时挤出话，前后句连续承接，句尾加重。',kind='mixed',phase='process',node={'双方.接触':'双手持续锁腕、未解除','青.阶段':'转体中持续下拉'},card={'opening':'抓握已经建立，青用全身继续带动对手。','beats':['闭眼鼓腮、双手夹牢','肩肘高起后下拉，汗甩离'],'coupling':'话语与持续用力交叠，不在气泡间松手。','landing':'腕部已被拉过脸侧，抡摔继续。'})
add('21_001',2,'16:9，青在画面左下折身，武士巨大身体从右上越过，腕臂连接与向下的大弧同时入画；镜头沿抡摔弧线下摇，落幅将坠向石地的武士与低头发力的青连在同一纵深。','青保持双手锁腕，上身向下折，头随肩压到手臂内侧；她的腰胯把最后一段转力送出去，武士巨大身体越过弧顶，胸腹和另一条粗臂一起向石面坠下。青长发先飞向上方，再追着头肩回扫，两手在坠落过程中始终没有松开。','浅冷灰天空从上方退去，下摇途中显出下方灰绿石铺地面与米灰薄尘。','上方云天冷白漫射，坠落身体下侧受石地微弱补光。','庞大躯体的下坠风声骤沉，青一次集中发力呼气，脚底与石面短擦。',ja=['やっぱりダメじゃない！！'],tone='把判断和最后一下抡摔一起顶出，短而用力。',kind='mixed',phase='process',node={'武士.阶段':'被抓腕抡过弧顶向石面坠落','青.阶段':'折身完成抡摔'},meaning='保留青折身、头低、持续抓腕与巨大对手越弧下坠，不强造一套与下一格不相接的翻身招式。')
